 const string Folder="TruckFishing";
 public static void Upgrade(){EditorSceneManager.OpenScene(FishingAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<FishingMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();FishingAuthoring.Validate();}
 public static void Install(FishingMatch m){var debris=new[]{Debris("Discarded tyre","Assets/RoadPropsPack/URP/Prefabs/Tire_URP.prefab",new Vector3(.9f,.5f,.9f)),Debris("Floating canister","Assets/RoadPropsPack/URP/Prefabs/Canister_URP.prefab",new Vector3(.7f,.8f,.5f)),Debris("River stone","Assets/Layer Lab/3D Characters-Fish/Fish/Prefabs/RockA.prefab",new Vector3(.8f,.5f,.7f))};var theme=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme");foreach(var stream in m.streams){stream.debrisPrefabs=debris;var qte=stream.GetComponent<FishingNetClear>();if(qte==null)qte=stream.gameObject.AddComponent<FishingNetClear>();qte.match=m;qte.slot=stream.slot;stream.clearing=qte;if(qte.panel==null){var viewport=SportsUIAuthoring.Rect("Local net challenge viewport "+stream.slot,m.menus.hud.transform,Vector2.zero,Vector2.zero).GetComponent<RectTransform>();SportsBroadcastCanvas.Stretch(viewport);var panel=SportsUIAuthoring.Rect("Rounded net-clearing card",viewport,new Vector2(510,170),new Vector2(0,80)).GetComponent<RectTransform>();panel.anchorMin=panel.anchorMax=new Vector2(.5f,0);panel.pivot=new Vector2(.5f,0);panel.gameObject.AddComponent<Image>().color=SportsBroadcastCanvas.Ink;panel.gameObject.AddComponent<SportsBroadcastPlate>().cut=16;var caption=SportsUIAuthoring.Text("Owned device shake prompts",panel,"NET SNAGGED!",new Vector2(460,120),new Vector2(0,12),34);caption.font=theme.bodyFont;caption.color=SportsBroadcastCanvas.Cream;var track=SportsUIAuthoring.Rect("Recovery meter track",panel,new Vector2(450,9),new Vector2(0,-65));track.AddComponent<Image>().color=SportsBroadcastCanvas.Raised;var fill=SportsUIAuthoring.Rect("Remaining clear time",track.transform,new Vector2(450,9),Vector2.zero).AddComponent<Image>();fill.sprite=AssetDatabase.GetBuiltinExtraResource<Sprite>("UI/Skin/UISprite.psd");fill.type=Image.Type.Filled;fill.fillMethod=Image.FillMethod.Horizontal;fill.fillOrigin=0;fill.color=SportsBroadcastCanvas.Orange;qte.panel=panel;qte.caption=caption;qte.timeBar=fill;qte.indicators.QTEIndicators=new[]{panel.gameObject};panel.gameObject.SetActive(false);}if(qte.snag==null){var model=(GameObject)PrefabUtility.InstantiatePrefab(debris[0]);model.name="Snagged rubbish in net";model.transform.SetParent(stream.netBag,false);model.transform.localPosition=new Vector3(0,-.03f,0);qte.snag=model.transform;model.SetActive(false);}Extend(stream,m.streamCameras[stream.slot].view);EditorUtility.SetDirty(stream);EditorUtility.SetDirty(qte);}EditorUtility.SetDirty(m);}
 static GameObject Debris(string name,string source,Vector3 size){string path="Assets/TruckFishing/Prefabs/"+name+".prefab";var saved=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(saved!=null)return saved;var root=new GameObject(name);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(root.transform,source,size,0,true,Folder);foreach(var c in root.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var rb in root.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(rb);saved=PrefabUtility.SaveAsPrefabAsset(root,path);UnityEngine.Object.DestroyImmediate(root);return saved;}
 static void Extend(FishingStream stream,Camera camera){camera.farClipPlane=Mathf.Max(camera.farClipPlane,180);var water=stream.transform.Find("River Modeler clear flowing surface").GetComponent<MeshFilter>().sharedMesh;var vertices=water.vertices;bool changed=false;for(int i=0;i<vertices.Length;i++)if(vertices[i].z>=35&&vertices[i].z<72){vertices[i].z=72;changed=true;}if(changed){water.vertices=vertices;water.RecalculateBounds();EditorUtility.SetDirty(water);}if(stream.transform.Find("Offscreen upstream river continuation")!=null)return;const string path="Assets/TruckFishing/Models/Offscreen upstream riverbank.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();data.heightmapResolution=129;data.size=new Vector3(36,4,44);data.terrainLayers=stream.GetComponentInChildren<Terrain>().terrainData.terrainLayers;var h=new float[129,129];for(int z=0;z<129;z++)for(int x=0;x<129;x++){float wx=-18+x*36f/128,wz=36+z*44f/128,edge=7.15f+.32f*Mathf.Sin(wz*.28f);float bank=Mathf.SmoothStep(0,1,Mathf.InverseLerp(edge-.4f,edge+1.5f,Mathf.Abs(wx)));h[z,x]=(Mathf.Lerp(-.7f,.65f,bank)+.11f*Mathf.PerlinNoise(wx*.3f+20,wz*.22f)*bank+2)/4;}data.SetHeights(0,0,h);data.alphamapResolution=128;var paint=new float[128,128,2];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float wx=-18+x*36f/127,wz=36+z*44f/127,edge=7.15f+.32f*Mathf.Sin(wz*.28f);float bank=Mathf.SmoothStep(0,1,Mathf.InverseLerp(edge+.1f,edge+1.3f,Mathf.Abs(wx)));paint[z,x,0]=bank;paint[z,x,1]=1-bank;}data.SetAlphamaps(0,0,paint);AssetDatabase.CreateAsset(data,path);}var original=stream.GetComponentInChildren<Terrain>();var go=Terrain.CreateTerrainGameObject(data);go.name="Offscreen upstream river continuation";go.transform.SetParent(stream.transform,false);go.transform.localPosition=new Vector3(-18,-2,36);var terrain=go.GetComponent<Terrain>();terrain.materialTemplate=original.materialTemplate;terrain.drawInstanced=true;terrain.heightmapPixelError=8;original.SetNeighbors(null,terrain,null,null);terrain.SetNeighbors(null,null,null,original);EditorUtility.SetDirty(camera);}
